zations_url":"https://api.github.com/users/chris-arsenault/orgs","received_events_url":"https://api.github.com/users/chris-arsenault/received_events","repos_url":"https://api.github.com/users/chris-arsenault/repos","site_admin":false,"starred_url":"https://api.github.com/users/chris-arsenault/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/chris-arsenault/subscriptions","type":"User","url":"https://api.github.com/users/chris-arsenault","user_view_type":"public"},"html_url":"https://github.com/chris-arsenault/the-canonry/commit/8e5bcadaf2860aeed6955531594b7571f747fcd3","node_id":"C_kwDORHOrMtoAKDhlNWJjYWRhZjI4NjBhZWVkNjk1NTUzMTU5NGI3NTcxZjc0N2ZjZDM","parents":[{"html_url":"https://github.com/chris-arsenault/the-canonry/commit/afd7e1289ae713b21f26425e725e815ec03769fb","sha":"afd7e1289ae713b21f26425e725e815ec03769fb","url":"https://api.github.com/repos/chris-arsenault/the-canonry/commits/afd7e1289ae713b21f26425e725e815ec03769fb"}],"sha":"8e5bcadaf2860aeed6955531594b7571f747fcd3","url":"https://api.github.com/repos/chris-arsenault/the-canonry/commits/8e5bcadaf2860aeed6955531594b7571f747fcd3"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/5192503?v=4","events_url":"https://api.github.com/users/chris-arsenault/events{/privacy}","followers_url":"https://api.github.com/users/chris-arsenault/followers","following_url":"https://api.github.com/users/chris-arsenault/following{/other_user}","gists_url":"https://api.github.com/users/chris-arsenault/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/chris-arsenault","id":5192503,"login":"chris-arsenault","node_id":"MDQ6VXNlcjUxOTI1MDM=","organizations_url":"https://api.github.com/users/chris-arsenault/orgs","received_events_url":"https://api.github.com/users/chris-arsenault/received_events","repos_url":"https://api.github.com/users/chris-arsenault/repos","site_admin":false,"starred_url":"https://api.github.com/users/chris-arsenault/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/chris-arsenault/subscriptions","type":"User","url":"https://api.github.com/users/chris-arsenault","user_view_type":"public"},"comments_url":"https://api.github.com/repos/chris-arsenault/the-canonry/commits/afd7e1289ae713b21f26425e725e815ec03769fb/comments","commit":{"author":{"date":"2026-03-03T18:10:59Z","email":"carsena2@gmail.com","name":"Chris Arsenault"},"comment_count":0,"committer":{"date":"2026-03-03T18:10:59Z","email":"carsena2@gmail.com","name":"Chris Arsenault"},"message":"fix: handle missing entityKinds on profiles and old temporal format on eras\n\n1. generate.ts: profiles loaded from persisted JSON may lack entityKinds\n   (the field was optional before type tightening). Normalize to empty\n   array at the generate() boundary before selectProfile accesses it.\n\n2. useChronicleNavigation.ts: era entities from IndexedDB may have the\n   old temporal format (endTick: number) instead of the new TickStatus\n   discriminated union (end: { occurred, tick }). Handle both formats.\n\nCo-Authored-By: Claude Opus 4.6 <noreply@anthropic.com>","tree":{"sha":"4551bfb50bc5cb51ea0b2d0730c912ce4aa51a33","url":"https://api.github.com/repos/chris-arsenault/the-canonry/git/trees/4551bfb50bc5cb51ea0b2d0730c912ce4aa51a33"},"url":"https://api.github.com/repos/chris-arsenault/the-canonry/git/commits/afd7e1289ae713b21f26425e725e815ec03769fb","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/5192503?v=4","events_url":"https://api.github.com/users/chris-arsenault/events{/privacy}","followers_url":"https://api.github.com/users/chris-arsenault/followers","following_url":"https://api.github.com/users/chris-arsenault/following{/other_user}","gists_url":"https://api.github.com/users/chris-arsenault/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/chris-arsenault","id":5192503,"login":"chris-arsenault","node_id":"M